{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("c", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_and_handles_empty_groups():
    groups = {"small": [event("a", 1, True)],
              "large": [event("b", 1, False), event("c", 1, None), event("d", 1, False)],
              "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_log_whitespace_comments_and_flag_values():
    lines = ["\n", "  # comment, with commas\n", " x , -2 , 1 \n",
             "y, 0, 0", "z, 4,   "]
    assert parse_transcript_log(lines) == [event("x", -2, True), event("y", 0, False),
                                          event("z", 4, None)]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,no,1", "x,1,true"])
def test_parse_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log([" ", " # comment", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts_by_day_then_id():
    first = event("a", 1, True)
    last = event("a", 3, None)
    events = [first, event("z", 3, True), event("b", 2, False), last,
              event("c", 3, False)]
    assert dedupe_transcripts(events) == [events[2], last, events[4], events[1]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_with_gaps_and_outside_events():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_weighting_and_nonempty_groups():
    events = [event("a", 1, True), event("b", 1, False), event("c", 1, False),
              event("d", 5, True), event("e", 5, False), event("f", 5, False)]
    groups = {"one": events[:1], "two": events[1:], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 10)["recent"] == 2
    assert monitor_summary({"empty": []}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("a", 1, True)], "empty": [],
              "a": [event("b", 1, True)], "b": [event("c", 1, False)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_sorts_names():
    groups = {"z": [], "b": [event("a", 1, None)], "a": [event("b", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_requires_consecutive_positive_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
